  ('lakshmi_ashtottara_108', 67, 'ॐ शिवकर्यै नमः', 'ஓம் ஶிவகர்யை நம꞉', 'ōṁ śivakaryai namaḥ'),
  ('lakshmi_ashtottara_108', 68, 'ॐ सत्यै नमः', 'ஓம் ஸத்யை நம꞉', 'ōṁ satyai namaḥ'),
  ('lakshmi_ashtottara_108', 69, 'ॐ विमलायै नमः', 'ஓம் விமலாயை நம꞉', 'ōṁ vimalāyai namaḥ'),
