  ('lakshmi_ashtottara_108', 76, 'ॐ श्रियै नमः', 'ஓம் ஶ்ரியை நம꞉', 'ōṁ śriyai namaḥ'),
  ('lakshmi_ashtottara_108', 77, 'ॐ भास्कर्यै नमः', 'ஓம் பாஸ்கர்யை நம꞉', 'ōṁ bhāskaryai namaḥ'),
  ('lakshmi_ashtottara_108', 78, 'ॐ बिल्वनिलयायै नमः', 'ஓம் பில்வநிலயாயை நம꞉', 'ōṁ bilvanilayāyai namaḥ'),
  ('lakshmi_ashtottara_108', 79, 'ॐ वरारोहायै नमः', 'ஓம் வராரோஹாயை நம꞉', 'ōṁ varārōhāyai namaḥ'),
  ('lakshmi_ashtottara_108', 80, 'ॐ यशस्विन्यै नमः', 'ஓம் யஶஸ்விந்யை நம꞉', 'ōṁ yaśasvinyai namaḥ'),
