  ('lakshmi_ashtottara_108', 82, 'ॐ उदाराङ्गायै नमः', 'ஓம் உதாராங்காயை நம꞉', 'ōṁ udārāṅgāyai namaḥ'),
  ('lakshmi_ashtottara_108', 83, 'ॐ हरिण्यै नमः', 'ஓம் ஹரிண்யை நம꞉', 'ōṁ hariṇyai namaḥ'),
