  ('lakshmi_ashtottara_108', 90, 'ॐ वरलक्ष्म्यै नमः', 'ஓம் வரலக்ஷ்ம்யை நம꞉', 'ōṁ varalakṣmyai namaḥ'),
  ('lakshmi_ashtottara_108', 91, 'ॐ वसुप्रदायै नमः', 'ஓம் வஸுப்ரதாயை நம꞉', 'ōṁ vasupradāyai namaḥ'),
  ('lakshmi_ashtottara_108', 92, 'ॐ शुभायै नमः', 'ஓம் ஶுபாயை நம꞉', 'ōṁ śubhāyai namaḥ'),
