-- --- the steps specific to this vratham --------------------------------------
-- 5. Manjal Pillaiyar Pooja
insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('varalakshmi_vratham', 5, 'purvangam', '{main,punar}',
        'Manjal Pillaiyar Pooja', 'மஞ்சள் பிள்ளையார் பூஜை',
        'Roll a small cone of turmeric paste on a betel leaf. That is the Pillaiyar for today. Invoke him, offer akshatai and a flower, and ask him to clear the way before the main pooja begins. He is not immersed or kept; at the end of the vratham he is set aside with the rest of the offerings.',
        'மஞ்சள் மாவை வெற்றிலையின் மேல் சிறு கூம்பாகப் பிடிக்கவும். அதுவே இன்றைய பிள்ளையார். அவரை ஆவாஹனம் செய்து, அக்ஷதையும் புஷ்பமும் சமர்ப்பித்து, பிரதான பூஜை தொடங்கும் முன் விக்கினங்களை நீக்கும்படி வேண்டவும். இவரை கரைப்பதோ வைத்திருப்பதோ இல்லை; விரதம் முடிந்தபின் மற்ற சமர்ப்பணங்களுடன் சேர்த்து எடுத்து வைக்கப்படுகிறார்.',
        'हरिद्राभं चतुर्बाहुं हरिद्रावदनं प्रभुम् । पाशांकुशधरं देवं मोदकं दंतमेव च । भक्ताऽभयप्रदातारं वंदे विघ्नविनाशनम् । ॐ हरिद्रा गणपतये नमः । अस्मिन् हरिद्राबिंबे श्रीमहागणपतिं आवाहयामि, स्थापयामि, पूजयामि ॥',
        'ஹரித்ராபம் சதுர்பாஹும் ஹரித்ராவதநம் ப்ரபும் । பாஶாம்குஶதரம் தேவம் மோதகம் தம்தமேவ ச । பக்தாऽபயப்ரதாதாரம் வம்தே விக்நவிநாஶநம் । ஓம் ஹரித்ரா கணபதயே நம꞉ । அஸ்மிந் ஹரித்ராபிம்பே ஶ்ரீமஹாகணபதிம் ஆவாஹயாமி, ஸ்தாபயாமி, பூஜயாமி ॥',
        'haridrābhaṃ caturbāhuṃ haridrāvadanaṃ prabhum । pāśāṃkuśadharaṃ devaṃ modakaṃ daṃtameva ca । bhaktā''bhayapradātāraṃ vaṃde vighnavināśanam । oṃ haridrā gaṇapataye namaḥ । asmin haridrābiṃbe śrīmahāgaṇapatiṃ āvāhayāmi, sthāpayāmi, pūjayāmi ॥',
        'Every pooja in this tradition opens by asking Ganesha to move first. Making him out of turmeric rather than fetching a metal idol is the point: the obstacle-remover is made from what is already on the kitchen shelf, in the minute before he is needed.', 'all', true, false,
        null, 'StotraNidhi Sri Haridra Ganapati Puja (Telugu); Sathya Vadyar, Varalakshmi Poojai 2026 step by step, chapter at 04:02. The full published vidhi also carries Vedic mantras with svara marks, which this app does not yet render and which are omitted here rather than shown unaccented.')
on conflict (pooja_id, step_number) do update set
  step_title_en = excluded.step_title_en, step_title_ta = excluded.step_title_ta,
  instruction_en = excluded.instruction_en, instruction_ta = excluded.instruction_ta,
  mantra_sanskrit = excluded.mantra_sanskrit, mantra_tamil = excluded.mantra_tamil,
  mantra_translit = excluded.mantra_translit, philosophy_en = excluded.philosophy_en,
  is_dynamic_sankalpam = excluded.is_dynamic_sankalpam,
  namavali_id = excluded.namavali_id, modes = excluded.modes,
  phase = excluded.phase, source_ref = excluded.source_ref;

-- 6. Sankalpam
insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('varalakshmi_vratham', 6, 'purvangam', '{main,punar,udvasana}',
        'Sankalpam', 'ஸங்கல்பம்',
        'Hold water in the right palm. State the day by the panchangam, then the intention: this is done for the household, for its wellbeing and for good fortune, addressing Varalakshmi. Release the water at the end.',
        'வலது உள்ளங்கையில் ஜலம் எடுக்கவும். பஞ்சாங்கப்படி இன்றைய நாளைச் சொல்லி, பின் சங்கல்பத்தைச் சொல்லவும் — இது குடும்பத்தின் க்ஷேமத்திற்காகவும் சௌபாக்யத்திற்காகவும், வரலக்ஷ்மியை உத்தேசித்துச் செய்யப்படுகிறது. முடிவில் ஜலத்தை விடவும்.',
        'शुभे शोभने मुहूर्ते आद्य ब्रह्मणः द्वितीय परार्धे श्वेत वराह कल्पे वैवस्वत मन्वन्तरे अष्टाविंशतितमे कलियुगे प्रथमे पादे जम्बूद्वीपे भरत वर्षे भरत खण्डे [DYNAMIC_PANCHANGAM_DATA] पूर्वोक्त एवं गुण विशेषण विशिष्टायां शुभतिथौ, अस्माकं सहकुटुंबानां क्षेमस्थैर्य विजयायुरारोग्य ऐश्वर्याभिवृद्ध्यर्थं धर्मार्थ काममोक्ष चतुर्विध पुरुषार्थ फल सिद्ध्यर्थं सत्संतान सौभाग्य फलावाप्त्यर्थं श्री वरलक्ष्मी देवतामुद्दिश्य श्री वरलक्ष्मी देवता प्रीत्यर्थं कल्पोक्त विधानेन यावच्छक्ति ध्यानावाहनादि षोडशोपचार पूजां करिष्ये ॥',
        'ஶுபே ஶோபநே முஹூர்தே ஆத்ய ப்ரஹ்மண꞉ த்விதீய பரார்தே ஶ்வேத வராஹ கல்பே வைவஸ்வத மந்வந்தரே அஷ்டாவிம்ஶதிதமே கலியுகே ப்ரதமே பாதே ஜம்பூத்வீபே பரத வர்ஷே பரத கண்டே [DYNAMIC_PANCHANGAM_DATA] பூர்வோக்த ஏவம் குண விஶேஷண விஶிஷ்டாயாம் ஶுபதிதௌ, அஸ்மாகம் ஸஹகுடும்பாநாம் க்ஷேமஸ்தைர்ய விஜயாயுராரோக்ய ஐஶ்வர்யாபிவ்ருத்த்யர்தம் தர்மார்த காமமோக்ஷ சதுர்வித புருஷார்த பல ஸித்த்யர்தம் ஸத்ஸம்தாந ஸௌபாக்ய பலாவாப்த்யர்தம் ஶ்ரீ வரலக்ஷ்மீ தேவதாமுத்திஶ்ய ஶ்ரீ வரலக்ஷ்மீ தேவதா ப்ரீத்யர்தம் கல்போக்த விதாநேந யாவச்சக்தி த்யாநாவாஹநாதி ஷோடஶோபசார பூஜாம் கரிஷ்யே ॥',
        'śubhe śobhane muhūrte ādya brahmaṇaḥ dvitīya parārdhe śveta varāha kalpe vaivasvata manvantare aṣṭāviṃśatitame kaliyuge prathame pāde jambūdvīpe bharata varṣe bharata khaṇḍe [DYNAMIC_PANCHANGAM_DATA] pūrvokta evaṃ guṇa viśeṣaṇa viśiṣṭāyāṃ śubhatithau, asmākaṃ sahakuṭuṃbānāṃ kṣemasthairya vijayāyurārogya aiśvaryābhivṛddhyarthaṃ dharmārtha kāmamokṣa caturvidha puruṣārtha phala siddhyarthaṃ satsaṃtāna saubhāgya phalāvāptyarthaṃ śrī varalakṣmī devatāmuddiśya śrī varalakṣmī devatā prītyarthaṃ kalpokta vidhānena yāvacchakti dhyānāvāhanādi ṣoḍaśopacāra pūjāṃ kariṣye ॥',
        'The sankalpam is the only place the pooja is dated, located and addressed. Everything after it is the same on any Friday; this sentence is what makes it today. Note who it is for: asmakam sahakutumbanam, ourselves together with the household, not the individual reciting it.', 'all', true, true,
        null, 'StotraNidhi Sri Varalakshmi Vrata Kalpam (Telugu), round-trip verified by scripts/parse-varalakshmi-kalpam.mjs; Sathya Vadyar, Varalakshmi Poojai 2026 step by step, chapters at 14:00 and 17:15')
on conflict (pooja_id, step_number) do update set
  step_title_en = excluded.step_title_en, step_title_ta = excluded.step_title_ta,
