  mantra_sanskrit = excluded.mantra_sanskrit, mantra_tamil = excluded.mantra_tamil,
  mantra_translit = excluded.mantra_translit, philosophy_en = excluded.philosophy_en,
  is_dynamic_sankalpam = excluded.is_dynamic_sankalpam,
  namavali_id = excluded.namavali_id, modes = excluded.modes,
  phase = excluded.phase, source_ref = excluded.source_ref;

-- 9. Peeta Pooja
insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('varalakshmi_vratham', 9, 'pradhana', '{main}',
        'Peeta Pooja', 'பீட பூஜை',
        'Before the goddess is invited, the seat is worshipped. Lay the rice, spread the mango or banyan leaves, set the kalasham with the Lakshmi face on it, and offer the seat itself with this verse.',
        'தேவியை எழுந்தருளச் செய்வதற்கு முன் ஆசனத்தைப் பூஜிக்க வேண்டும். அரிசியைப் பரப்பி, மாவிலை அல்லது ஆலிலையை வைத்து, லக்ஷ்மி முகம் பொருந்திய கலசத்தை நிறுத்தி, இந்த ஸ்லோகத்தால் ஆசனத்தைச் சமர்ப்பிக்கவும்.',
        'सूर्यायुत निभस्फूर्ते स्फुरद्रत्नविभूषिते ।
सिंहासनमिदं देवी स्थीयतां सुरपूजिते ॥
श्री वरलक्ष्मी देवतायै नमः रत्नसिंहासनं समर्पयामि ॥',
        'ஸூர்யாயுத நிபஸ்பூர்தே ஸ்புரத்ரத்நவிபூஷிதே ।
ஸிம்ஹாஸநமிதம் தேவீ ஸ்தீயதாம் ஸுரபூஜிதே ॥
ஶ்ரீ வரலக்ஷ்மீ தேவதாயை நம꞉ ரத்நஸிம்ஹாஸநம் ஸமர்பயாமி ॥',
        'sūryāyuta nibhasphūrte sphuradratnavibhūṣite ।
siṃhāsanamidaṃ devī sthīyatāṃ surapūjite ॥
śrī varalakṣmī devatāyai namaḥ ratnasiṃhāsanaṃ samarpayāmi ॥',
        'You prepare the chair before the guest arrives, not after. Peeta Pooja is the step most often skipped at home and the one that makes the difference between placing an object and receiving a person.', 'all', true, false,
        null, 'StotraNidhi Sri Varalakshmi Vrata Kalpam (Telugu), round-trip verified by scripts/parse-varalakshmi-kalpam.mjs; Sathya Vadyar, Varalakshmi Poojai 2026 step by step, chapter at 24:54')
on conflict (pooja_id, step_number) do update set
  step_title_en = excluded.step_title_en, step_title_ta = excluded.step_title_ta,
  instruction_en = excluded.instruction_en, instruction_ta = excluded.instruction_ta,
  mantra_sanskrit = excluded.mantra_sanskrit, mantra_tamil = excluded.mantra_tamil,
  mantra_translit = excluded.mantra_translit, philosophy_en = excluded.philosophy_en,
  is_dynamic_sankalpam = excluded.is_dynamic_sankalpam,
  namavali_id = excluded.namavali_id, modes = excluded.modes,
  phase = excluded.phase, source_ref = excluded.source_ref;

-- 10. Dhyanam & Avahanam
insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('varalakshmi_vratham', 10, 'pradhana', '{main}',
        'Dhyanam & Avahanam', 'த்யானம் & ஆவாஹனம்',
        'Close your eyes and hold the form in mind: seated on the lotus, lotus in hand, dear to Narayana, risen from the ocean of milk. Then invite her, with folded hands, to stay in this house. Done once, on the first day only.',
        'கண்களை மூடி வடிவத்தை மனதில் நிறுத்தவும் — தாமரையில் அமர்ந்து, கையில் தாமரையுடன், நாராயணனுக்குப் பிரியமானவள், பாற்கடலில் தோன்றியவள். பின் கைகூப்பி, இந்த வீட்டில் நிலைத்திருக்கும்படி அழைக்கவும். இது முதல் நாளில் மட்டும் ஒரு முறை.',
        'पद्मासने पद्मकरे सर्वलोकैक पूजिते ।
नारायणप्रिये देवी सुप्रीता भव सर्वदा ॥
क्षीरोदार्णव संभूते कमले कमलालये
सुस्थिरा भव मे गेहे सुरासुर नमस्कृते ॥
श्री वरलक्ष्मी देवतायै नमः ध्यायामि ॥
सर्वमंगळ मांगळ्ये विष्णुवक्षस्स्थलालये ।
आवहयामि देवी त्वां सुप्रीता भव सर्वदा ॥
श्री वरलक्ष्मी देवतायै नमः आवहयामि ॥',
        'பத்மாஸநே பத்மகரே ஸர்வலோகைக பூஜிதே ।
நாராயணப்ரியே தேவீ ஸுப்ரீதா பவ ஸர்வதா ॥
க்ஷீரோதார்ணவ ஸம்பூதே கமலே கமலாலயே
ஸுஸ்திரா பவ மே கேஹே ஸுராஸுர நமஸ்க்ருதே ॥
ஶ்ரீ வரலக்ஷ்மீ தேவதாயை நம꞉ த்யாயாமி ॥
ஸர்வமம்கள மாம்கள்யே விஷ்ணுவக்ஷஸ்ஸ்தலாலயே ।
ஆவஹயாமி தேவீ த்வாம் ஸுப்ரீதா பவ ஸர்வதா ॥
ஶ்ரீ வரலக்ஷ்மீ தேவதாயை நம꞉ ஆவஹயாமி ॥',
        'padmāsane padmakare sarvalokaika pūjite ।
nārāyaṇapriye devī suprītā bhava sarvadā ॥
kṣīrodārṇava saṃbhūte kamale kamalālaye
susthirā bhava me gehe surāsura namaskṛte ॥
śrī varalakṣmī devatāyai namaḥ dhyāyāmi ॥
sarvamaṃgal̤a māṃgal̤ye viṣṇuvakṣassthalālaye ।
āvahayāmi devī tvāṃ suprītā bhava sarvadā ॥
śrī varalakṣmī devatāyai namaḥ āvahayāmi ॥',
        'Susthira bhava me gehe, "be settled in my house". The request is not for a visit. That is why Avahanam is not repeated on the second day: she was not asked to leave.', 'all', true, false,
        null, 'StotraNidhi Sri Varalakshmi Vrata Kalpam (Telugu), round-trip verified by scripts/parse-varalakshmi-kalpam.mjs; Sathya Vadyar, Varalakshmi Poojai 2026 step by step, chapter at 25:57')
on conflict (pooja_id, step_number) do update set
  step_title_en = excluded.step_title_en, step_title_ta = excluded.step_title_ta,
  instruction_en = excluded.instruction_en, instruction_ta = excluded.instruction_ta,
  mantra_sanskrit = excluded.mantra_sanskrit, mantra_tamil = excluded.mantra_tamil,
  mantra_translit = excluded.mantra_translit, philosophy_en = excluded.philosophy_en,
  is_dynamic_sankalpam = excluded.is_dynamic_sankalpam,
  namavali_id = excluded.namavali_id, modes = excluded.modes,
  phase = excluded.phase, source_ref = excluded.source_ref;

-- 11. Prana Pratishtha
insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('varalakshmi_vratham', 11, 'pradhana', '{main}',
        'Prana Pratishtha', 'ப்ராண ப்ரதிஷ்டை',
        'Touch the kalasham with the fingertips of the right hand and ask the life breath to settle into it. From here the kalasham is treated as present, not as an arrangement of vessels. The feminine form of the verse is used, asyai rather than asya.',
        'வலது கை விரல் நுனிகளால் கலசத்தைத் தொட்டு, உயிர்ப்பு அதில் நிலைபெறும்படி வேண்டவும். இதற்குப் பின் கலசம் பாத்திரங்களின் அமைப்பு அல்ல; எழுந்தருளியிருப்பவளாகவே கருதப்படுகிறது. ஸ்லோகத்தின் ஸ்த்ரீலிங்க வடிவம் — அஸ்ய அல்ல, அஸ்யை.',
        'अस्यै प्राणाः प्रतिष्ठन्तु अस्यै प्राणाः क्षरन्तु च । अस्यै देवत्वमर्चायै मामहेति च कश्चन ॥ श्री वरलक्ष्मी देवतायै नमः प्राण प्रतिष्ठापयामि ॥',
        'அஸ்யை ப்ராணா꞉ ப்ரதிஷ்டந்து அஸ்யை ப்ராணா꞉ க்ஷரந்து ச । அஸ்யை தேவத்வமர்சாயை மாமஹேதி ச கஶ்சந ॥ ஶ்ரீ வரலக்ஷ்மீ தேவதாயை நம꞉ ப்ராண ப்ரதிஷ்டாபயாமி ॥',
        'asyai prāṇāḥ pratiṣṭhantu asyai prāṇāḥ kṣarantu ca । asyai devatvamarcāyai māmaheti ca kaścana ॥ śrī varalakṣmī devatāyai namaḥ prāṇa pratiṣṭhāpayāmi ॥',
        'The same verse as at Ganesha Chaturthi, in the feminine. It is what turns the rest of the morning into hospitality rather than arrangement, and it is why the kalasham is dismantled the next day with a step of its own instead of simply being put away.', 'all', true, false,
        null, 'Standard prana pratishtha verse, feminine form; Sathya Vadyar, Varalakshmi Poojai 2026 step by step, chapter at 29:26')
on conflict (pooja_id, step_number) do update set
  step_title_en = excluded.step_title_en, step_title_ta = excluded.step_title_ta,
  instruction_en = excluded.instruction_en, instruction_ta = excluded.instruction_ta,
  mantra_sanskrit = excluded.mantra_sanskrit, mantra_tamil = excluded.mantra_tamil,
  mantra_translit = excluded.mantra_translit, philosophy_en = excluded.philosophy_en,
  is_dynamic_sankalpam = excluded.is_dynamic_sankalpam,
  namavali_id = excluded.namavali_id, modes = excluded.modes,
  phase = excluded.phase, source_ref = excluded.source_ref;

-- 12. Padyam, Arghyam & Achamaniyam
insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('varalakshmi_vratham', 12, 'pradhana', '{main,punar}',
        'Padyam, Arghyam & Achamaniyam', 'பாத்யம், அர்க்யம் & ஆசமனீயம்',
        'The first three courtesies given to any guest who arrives on foot: water for the feet, water for the hands, water to sip. Pour a spoonful into the uddharani at each and empty it into the plate.',
        'நடந்து வரும் விருந்தினருக்குச் செய்யும் முதல் மூன்று உபசாரங்கள் — பாதம் கழுவ ஜலம், கை கழுவ ஜலம், பருக ஜலம். ஒவ்வொன்றிலும் உத்தரிணியில் ஒரு ஸ்பூன் ஜலம் விட்டு தாம்பாளத்தில் ஊற்றவும்.',
        'शुद्धोदकं च पात्रस्थं गंध पुष्पादि मिश्रितं ।
अर्घ्यं दास्यामि ते देवी गृह्यतां हरिवल्लभे ॥
श्री वरलक्ष्मी देवतायै नमः अर्घ्यं समर्पयामि ॥
सुवासित जलं रम्यं सर्वतीर्थ समुद्भवं ।
पाद्यं गृहाण देवी त्वं सर्वदेव नमस्कृते ॥
श्री वरलक्ष्मी देवतायै नमः पाद्यं समर्पयामि ॥
सुवर्ण कलशानीतं चंदनागरु संयुतं ।
गृहाणाचमनं देवी मयादत्तं शुभप्रदे ॥
श्री वरलक्ष्मी देवतायै नमः आचमनीयं समर्पयामि ॥',
        'ஶுத்தோதகம் ச பாத்ரஸ்தம் கம்த புஷ்பாதி மிஶ்ரிதம் ।
அர்க்யம் தாஸ்யாமி தே தேவீ க்ருஹ்யதாம் ஹரிவல்லபே ॥
ஶ்ரீ வரலக்ஷ்மீ தேவதாயை நம꞉ அர்க்யம் ஸமர்பயாமி ॥
ஸுவாஸித ஜலம் ரம்யம் ஸர்வதீர்த ஸமுத்பவம் ।
பாத்யம் க்ருஹாண தேவீ த்வம் ஸர்வதேவ நமஸ்க்ருதே ॥
ஶ்ரீ வரலக்ஷ்மீ தேவதாயை நம꞉ பாத்யம் ஸமர்பயாமி ॥
ஸுவர்ண கலஶாநீதம் சம்தநாகரு ஸம்யுதம் ।
க்ருஹாணாசமநம் தேவீ மயாதத்தம் ஶுபப்ரதே ॥
ஶ்ரீ வரலக்ஷ்மீ தேவதாயை நம꞉ ஆசமநீயம் ஸமர்பயாமி ॥',
        'śuddhodakaṃ ca pātrasthaṃ gaṃdha puṣpādi miśritaṃ ।
arghyaṃ dāsyāmi te devī gṛhyatāṃ harivallabhe ॥
śrī varalakṣmī devatāyai namaḥ arghyaṃ samarpayāmi ॥
suvāsita jalaṃ ramyaṃ sarvatīrtha samudbhavaṃ ।
pādyaṃ gṛhāṇa devī tvaṃ sarvadeva namaskṛte ॥
śrī varalakṣmī devatāyai namaḥ pādyaṃ samarpayāmi ॥
suvarṇa kalaśānītaṃ caṃdanāgaru saṃyutaṃ ।
gṛhāṇācamanaṃ devī mayādattaṃ śubhaprade ॥
śrī varalakṣmī devatāyai namaḥ ācamanīyaṃ samarpayāmi ॥',
        'These three are older than any temple. They are what a household in a hot country did for anyone who reached the door, and the pooja preserves them unchanged.', 'all', true, false,
        null, 'StotraNidhi Sri Varalakshmi Vrata Kalpam (Telugu), round-trip verified by scripts/parse-varalakshmi-kalpam.mjs; Sathya Vadyar, Varalakshmi Poojai 2026 step by step, chapter at 32:25')
on conflict (pooja_id, step_number) do update set
  step_title_en = excluded.step_title_en, step_title_ta = excluded.step_title_ta,
  instruction_en = excluded.instruction_en, instruction_ta = excluded.instruction_ta,
  mantra_sanskrit = excluded.mantra_sanskrit, mantra_tamil = excluded.mantra_tamil,
  mantra_translit = excluded.mantra_translit, philosophy_en = excluded.philosophy_en,
  is_dynamic_sankalpam = excluded.is_dynamic_sankalpam,
  namavali_id = excluded.namavali_id, modes = excluded.modes,
  phase = excluded.phase, source_ref = excluded.source_ref;

-- 13. Panchamrita & Shuddhodaka Snanam
insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('varalakshmi_vratham', 13, 'pradhana', '{main,punar}',
        'Panchamrita & Shuddhodaka Snanam', 'பஞ்சாம்ருத & ஶுத்தோதக ஸ்நானம்',
        'Bathe the Lakshmi face or the coin in the kalasham: first the five nectars, milk, curd, ghee, honey and sugar together, then clean water to finish. If the kalasham is already dressed, offer both symbolically with the uddharani into the plate.',
        'கலசத்தின் லக்ஷ்மி முகத்தையோ நாணயத்தையோ அபிஷேகம் செய்யவும் — முதலில் பஞ்சாம்ருதம் (பால், தயிர், நெய், தேன், சர்க்கரை), பின் ஶுத்தோதகம். கலசம் ஏற்கெனவே அலங்கரிக்கப்பட்டிருந்தால், உத்தரிணியால் தாம்பாளத்தில் விட்டு ஸாங்கேதிகமாகச் சமர்ப்பிக்கவும்.',
        'पयोदधि घृतोपेतं शर्करामधु संयुतं ।
पंचामृतस्नानमिदं गृहाण कमलालये ॥
श्री वरलक्ष्मी देवतायै नमः पंचामृतस्नानं समर्पयामि ॥
गंगाजलं मयाऽनीतं महादेवशिरस्स्थितं ।
शुद्धोदक स्नानमिदं गृहाण विधुसोदरि ॥
श्री वरलक्ष्मी देवतायै नमः शुद्धोदक स्नानं समर्पयामि ॥
स्नानानंतरं आचमनीयं समर्पयामि ।',
        'பயோததி க்ருதோபேதம் ஶர்கராமது ஸம்யுதம் ।
பம்சாம்ருதஸ்நாநமிதம் க்ருஹாண கமலாலயே ॥
ஶ்ரீ வரலக்ஷ்மீ தேவதாயை நம꞉ பம்சாம்ருதஸ்நாநம் ஸமர்பயாமி ॥
கம்காஜலம் மயாऽநீதம் மஹாதேவஶிரஸ்ஸ்திதம் ।
ஶுத்தோதக ஸ்நாநமிதம் க்ருஹாண விதுஸோதரி ॥
ஶ்ரீ வரலக்ஷ்மீ தேவதாயை நம꞉ ஶுத்தோதக ஸ்நாநம் ஸமர்பயாமி ॥
ஸ்நாநாநம்தரம் ஆசமநீயம் ஸமர்பயாமி ।',
        'payodadhi ghṛtopetaṃ śarkarāmadhu saṃyutaṃ ।
paṃcāmṛtasnānamidaṃ gṛhāṇa kamalālaye ॥
śrī varalakṣmī devatāyai namaḥ paṃcāmṛtasnānaṃ samarpayāmi ॥
gaṃgājalaṃ mayā''nītaṃ mahādevaśirassthitaṃ ।
śuddhodaka snānamidaṃ gṛhāṇa vidhusodari ॥
śrī varalakṣmī devatāyai namaḥ śuddhodaka snānaṃ samarpayāmi ॥
snānānaṃtaraṃ ācamanīyaṃ samarpayāmi ।',
        'Ganga jalam maya anitam, "I have brought Ganga water". Whatever is actually in the vessel, the sentence says what it is being treated as, and the treating is the rite.', 'all', true, false,
        null, 'StotraNidhi Sri Varalakshmi Vrata Kalpam (Telugu), round-trip verified by scripts/parse-varalakshmi-kalpam.mjs; Sathya Vadyar, Varalakshmi Poojai 2026 step by step, chapter at 32:25')
on conflict (pooja_id, step_number) do update set
  step_title_en = excluded.step_title_en, step_title_ta = excluded.step_title_ta,
  instruction_en = excluded.instruction_en, instruction_ta = excluded.instruction_ta,
  mantra_sanskrit = excluded.mantra_sanskrit, mantra_tamil = excluded.mantra_tamil,
  mantra_translit = excluded.mantra_translit, philosophy_en = excluded.philosophy_en,
  is_dynamic_sankalpam = excluded.is_dynamic_sankalpam,
  namavali_id = excluded.namavali_id, modes = excluded.modes,
  phase = excluded.phase, source_ref = excluded.source_ref;

-- 14. Vastram, Abharanam & Mangalyam
insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('varalakshmi_vratham', 14, 'pradhana', '{main,punar}',
        'Vastram, Abharanam & Mangalyam', 'வஸ்த்ரம், ஆபரணம் & மாங்கல்யம்',
        'Offer the two cloths, then the ornaments, then the mangalyam. A small new blouse-piece and whatever gold the house has are what is usually used. This is the sequence that makes the kalasham a married woman of the household rather than a vessel.',
        'இரண்டு வஸ்திரங்கள், பின் ஆபரணங்கள், பின் மாங்கல்யம் சமர்ப்பிக்கவும். பொதுவாக ஒரு புதிய ரவிக்கைத் துணியும், வீட்டில் உள்ள தங்க நகைகளும் பயன்படுத்தப்படுகின்றன. இந்த வரிசைதான் கலசத்தை ஒரு பாத்திரமாக அல்லாமல், வீட்டுச் சுமங்கலியாக ஆக்குகிறது.',
        'सुरार्चितांघ्रि युगळे दुकूलवसनप्रिये ।
वस्त्रयुग्मं प्रदास्यामि गृहाण सुरपूजिते ॥
श्री वरलक्ष्मी देवतायै नमः वस्त्रयुग्मं समर्पयामि ॥
केयूर कंकणा दिव्ये हार नूपुर मेखलाः ।
विभूषणान्य मूल्यानि गृहाण ऋषिपूजिते ॥
श्री वरलक्ष्मी देवतायै नमः आभरणानि समर्पयामि ॥
तप्तहेमकृतं देवी मांगळ्यं मंगळप्रदं ।
मया समर्पितं देवी गृहाण त्वं शुभप्रदे ॥
श्री वरलक्ष्मी देवतायै नमः मांगळ्यं समर्पयामि ॥',
        'ஸுரார்சிதாம்க்ரி யுகளே துகூலவஸநப்ரியே ।
வஸ்த்ரயுக்மம் ப்ரதாஸ்யாமி க்ருஹாண ஸுரபூஜிதே ॥
ஶ்ரீ வரலக்ஷ்மீ தேவதாயை நம꞉ வஸ்த்ரயுக்மம் ஸமர்பயாமி ॥
கேயூர கம்கணா திவ்யே ஹார நூபுர மேகலா꞉ ।
விபூஷணாந்ய மூல்யாநி க்ருஹாண ருஷிபூஜிதே ॥
ஶ்ரீ வரலக்ஷ்மீ தேவதாயை நம꞉ ஆபரணாநி ஸமர்பயாமி ॥
தப்தஹேமக்ருதம் தேவீ மாம்கள்யம் மம்களப்ரதம் ।
மயா ஸமர்பிதம் தேவீ க்ருஹாண த்வம் ஶுபப்ரதே ॥
ஶ்ரீ வரலக்ஷ்மீ தேவதாயை நம꞉ மாம்கள்யம் ஸமர்பயாமி ॥',
        'surārcitāṃghri yugal̤e dukūlavasanapriye ।
vastrayugmaṃ pradāsyāmi gṛhāṇa surapūjite ॥
śrī varalakṣmī devatāyai namaḥ vastrayugmaṃ samarpayāmi ॥
keyūra kaṃkaṇā divye hāra nūpura mekhalāḥ ।
vibhūṣaṇānya mūlyāni gṛhāṇa ṛṣipūjite ॥
śrī varalakṣmī devatāyai namaḥ ābharaṇāni samarpayāmi ॥
taptahemakṛtaṃ devī māṃgal̤yaṃ maṃgal̤apradaṃ ।
mayā samarpitaṃ devī gṛhāṇa tvaṃ śubhaprade ॥
śrī varalakṣmī devatāyai namaḥ māṃgal̤yaṃ samarpayāmi ॥',
        'The mangalyam verse is in none of the male deities'' poojas. It is the step where the vratham stops being worship of a goddess in general and becomes the household''s women dressing one of their own.', 'all', true, false,
        null, 'StotraNidhi Sri Varalakshmi Vrata Kalpam (Telugu), round-trip verified by scripts/parse-varalakshmi-kalpam.mjs; Sathya Vadyar, Varalakshmi Poojai 2026 step by step, chapter at 32:25')
on conflict (pooja_id, step_number) do update set
  step_title_en = excluded.step_title_en, step_title_ta = excluded.step_title_ta,
  instruction_en = excluded.instruction_en, instruction_ta = excluded.instruction_ta,
  mantra_sanskrit = excluded.mantra_sanskrit, mantra_tamil = excluded.mantra_tamil,
  mantra_translit = excluded.mantra_translit, philosophy_en = excluded.philosophy_en,
  is_dynamic_sankalpam = excluded.is_dynamic_sankalpam,
  namavali_id = excluded.namavali_id, modes = excluded.modes,
  phase = excluded.phase, source_ref = excluded.source_ref;

-- 15. Gandham, Akshatai & Pushpam
insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('varalakshmi_vratham', 15, 'pradhana', '{main,punar}',
        'Gandham, Akshatai & Pushpam', 'கந்தம், அக்ஷதை & புஷ்பம்',
        'Sandal paste, then turmeric-and-kumkumam rice, then flowers. The thamarai poo goes here and it is the one flower this vratham does not do without.',
        'சந்தனம், பின் மஞ்சளும் குங்குமமும் கலந்த அக்ஷதை, பின் புஷ்பங்கள். தாமரைப் பூ இங்கே சமர்ப்பிக்கப்படுகிறது; இந்த விரதத்தில் தவிர்க்க முடியாத ஒரே பூ அதுவே.',
        'कर्पूरागरु कस्तूरि रोचनादिभिरन्वितं ।
गंधं दास्याम्यहं देवि प्रीत्यर्थं प्रतिगृह्यतां ॥
श्री वरलक्ष्मी देवतायै नमः गंधं समर्पयामि ॥
अक्षतान् धवळान् दिव्यान् शालीयान् तंडुलान् शूभान् ।
हरिद्रा कुंकुमोपेतान् गृह्यतामब्धिपुत्रिके ॥
श्री वरलक्ष्मी देवतायै नमः अक्षतान् समर्पयामि
मल्लिका जाजिकुसुमैश्चंपकैर्वकुळैरपि ।
शतपत्रैश्च कल्हारैः पूजयामि हरिप्रिये ॥
श्री वरलक्ष्मी देवतायै नमः पुष्पाणि पूजयामि ॥',
        'கர்பூராகரு கஸ்தூரி ரோசநாதிபிரந்விதம் ।
கம்தம் தாஸ்யாம்யஹம் தேவி ப்ரீத்யர்தம் ப்ரதிக்ருஹ்யதாம் ॥
ஶ்ரீ வரலக்ஷ்மீ தேவதாயை நம꞉ கம்தம் ஸமர்பயாமி ॥
அக்ஷதாந் தவளாந் திவ்யாந் ஶாலீயாந் தம்டுலாந் ஶூபாந் ।
ஹரித்ரா கும்குமோபேதாந் க்ருஹ்யதாமப்திபுத்ரிகே ॥
ஶ்ரீ வரலக்ஷ்மீ தேவதாயை நம꞉ அக்ஷதாந் ஸமர்பயாமி
மல்லிகா ஜாஜிகுஸுமைஶ்சம்பகைர்வகுளைரபி ।
ஶதபத்ரைஶ்ச கல்ஹாரை꞉ பூஜயாமி ஹரிப்ரியே ॥
ஶ்ரீ வரலக்ஷ்மீ தேவதாயை நம꞉ புஷ்பாணி பூஜயாமி ॥',
        'karpūrāgaru kastūri rocanādibhiranvitaṃ ।
gaṃdhaṃ dāsyāmyahaṃ devi prītyarthaṃ pratigṛhyatāṃ ॥
śrī varalakṣmī devatāyai namaḥ gaṃdhaṃ samarpayāmi ॥
akṣatān dhaval̤ān divyān śālīyān taṃḍulān śūbhān ।
haridrā kuṃkumopetān gṛhyatāmabdhiputrike ॥
śrī varalakṣmī devatāyai namaḥ akṣatān samarpayāmi
mallikā jājikusumaiścaṃpakairvakul̤airapi ।
śatapatraiśca kalhāraiḥ pūjayāmi haripriye ॥
śrī varalakṣmī devatāyai namaḥ puṣpāṇi pūjayāmi ॥',
        'Mallika, jaji, champaka, vakula, shatapatra, kalhara. The verse names six flowers and expects none of them in particular; it is a way of saying "the best that is in the garden".', 'all', true, false,
        null, 'StotraNidhi Sri Varalakshmi Vrata Kalpam (Telugu), round-trip verified by scripts/parse-varalakshmi-kalpam.mjs; Sathya Vadyar, Varalakshmi Poojai 2026 step by step, chapter at 32:25')
