-- 18. Dhoopam & Deepam
insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('varalakshmi_vratham', 18, 'uttara', '{main,punar,udvasana}',
        'Dhoopam & Deepam', 'தூபம் & தீபம்',
        'Light the agarbatti and circle it, then show the ghee lamp. Ring the bell through both.',
        'ஊதுபத்தியை ஏற்றிச் சுற்றவும், பின் நெய் தீபத்தைக் காட்டவும். இரண்டின் போதும் மணி அடிக்கவும்.',
        'दशांगं गुग्गुलोपेतं सुगंधं च मनोहरं ।
धूपं दास्यामि ते देवी गृहाण कमलप्रिये ॥
श्री वरलक्ष्मी देवतायै नमः धूपमाघ्रपयामि ॥
घृताक्तवर्ति समायुक्तं अंधकार विनाशकं ।
दीपं दास्यामि ते देवी गृहाणमुदिता भव ॥
श्री वरलक्ष्मी देवतायै नमः दीपं समर्पयामि ॥',
        'தஶாம்கம் குக்குலோபேதம் ஸுகம்தம் ச மநோஹரம் ।
தூபம் தாஸ்யாமி தே தேவீ க்ருஹாண கமலப்ரியே ॥
ஶ்ரீ வரலக்ஷ்மீ தேவதாயை நம꞉ தூபமாக்ரபயாமி ॥
க்ருதாக்தவர்தி ஸமாயுக்தம் அம்தகார விநாஶகம் ।
தீபம் தாஸ்யாமி தே தேவீ க்ருஹாணமுதிதா பவ ॥
ஶ்ரீ வரலக்ஷ்மீ தேவதாயை நம꞉ தீபம் ஸமர்பயாமி ॥',
        'daśāṃgaṃ guggulopetaṃ sugaṃdhaṃ ca manoharaṃ ।
dhūpaṃ dāsyāmi te devī gṛhāṇa kamalapriye ॥
śrī varalakṣmī devatāyai namaḥ dhūpamāghrapayāmi ॥
ghṛtāktavarti samāyuktaṃ aṃdhakāra vināśakaṃ ।
dīpaṃ dāsyāmi te devī gṛhāṇamuditā bhava ॥
śrī varalakṣmī devatāyai namaḥ dīpaṃ samarpayāmi ॥',
        'Dhoopam is what the room smells of and deepam is what it looks like. Between them they are the only upacharas that reach everyone present rather than only the person doing the pooja.', 'all', true, false,
        null, 'StotraNidhi Sri Varalakshmi Vrata Kalpam (Telugu), round-trip verified by scripts/parse-varalakshmi-kalpam.mjs; Sathya Vadyar, Varalakshmi Poojai 2026 step by step, chapter at 47:34')
on conflict (pooja_id, step_number) do update set
  step_title_en = excluded.step_title_en, step_title_ta = excluded.step_title_ta,
  instruction_en = excluded.instruction_en, instruction_ta = excluded.instruction_ta,
  mantra_sanskrit = excluded.mantra_sanskrit, mantra_tamil = excluded.mantra_tamil,
  mantra_translit = excluded.mantra_translit, philosophy_en = excluded.philosophy_en,
  is_dynamic_sankalpam = excluded.is_dynamic_sankalpam,
  namavali_id = excluded.namavali_id, modes = excluded.modes,
  phase = excluded.phase, source_ref = excluded.source_ref;

-- 19. Naivedyam, Paniyam & Tambulam
insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('varalakshmi_vratham', 19, 'uttara', '{main,punar,udvasana}',
        'Naivedyam, Paniyam & Tambulam', 'நைவேத்யம், பானீயம் & தாம்பூலம்',
        'Place the food in front, sprinkle water around it, and offer it with the five breath mantras. Then water to drink, then the betel leaf and areca nut. Cover the food while reciting, and do not taste anything before this step.',
        'நைவேத்யத்தை முன்னே வைத்து, சுற்றி ஜலம் தெளித்து, பஞ்ச ப்ராண மந்திரங்களால் சமர்ப்பிக்கவும். பின் பருக ஜலம், பின் வெற்றிலை பாக்கு. சொல்லும்போது உணவை மூடி வைக்கவும்; இந்தப் படிக்கு முன் எதையும் ருசி பார்க்கக் கூடாது.',
        'ॐ प्राणाय स्वाहा । ॐ अपानाय स्वाहा । ॐ व्यानाय स्वाहा । ॐ उदानाय स्वाहा । ॐ समानाय स्वाहा ॥
नैवेद्यं षड्रसोपेतं दधि मध्वाज्य संयुतं ।
नानाभक्ष्यफलोपेतं गृहाण हरिवल्लभे ॥
श्री वरलक्ष्मी देवतायै नमः नैवेद्यं समर्पयामि ॥
घनसार सुगंधेन मिश्रितं पुष्पवासितं ।
पानीयं गृह्यतां देवी शीतलं सुमनोहरं ॥
श्री वरलक्ष्मी देवतायै नमः पानीयं समर्पयामि ॥
पूगीफल समायुक्तं नागवल्ली दळैर्युतं ।
कर्पूर चूर्ण संयुक्तं तांबूलं प्रतिगृह्यतां ॥
श्री वरलक्ष्मी देवतायै नमः तांबूलं समर्पयामि ॥',
        'ஓம் ப்ராணாய ஸ்வாஹா । ஓம் அபாநாய ஸ்வாஹா । ஓம் வ்யாநாய ஸ்வாஹா । ஓம் உதாநாய ஸ்வாஹா । ஓம் ஸமாநாய ஸ்வாஹா ॥
நைவேத்யம் ஷட்ரஸோபேதம் ததி மத்வாஜ்ய ஸம்யுதம் ।
நாநாபக்ஷ்யபலோபேதம் க்ருஹாண ஹரிவல்லபே ॥
ஶ்ரீ வரலக்ஷ்மீ தேவதாயை நம꞉ நைவேத்யம் ஸமர்பயாமி ॥
கநஸார ஸுகம்தேந மிஶ்ரிதம் புஷ்பவாஸிதம் ।
பாநீயம் க்ருஹ்யதாம் தேவீ ஶீதலம் ஸுமநோஹரம் ॥
ஶ்ரீ வரலக்ஷ்மீ தேவதாயை நம꞉ பாநீயம் ஸமர்பயாமி ॥
பூகீபல ஸமாயுக்தம் நாகவல்லீ தளைர்யுதம் ।
கர்பூர சூர்ண ஸம்யுக்தம் தாம்பூலம் ப்ரதிக்ருஹ்யதாம் ॥
ஶ்ரீ வரலக்ஷ்மீ தேவதாயை நம꞉ தாம்பூலம் ஸமர்பயாமி ॥',
        'oṃ prāṇāya svāhā । oṃ apānāya svāhā । oṃ vyānāya svāhā । oṃ udānāya svāhā । oṃ samānāya svāhā ॥
naivedyaṃ ṣaḍrasopetaṃ dadhi madhvājya saṃyutaṃ ।
nānābhakṣyaphalopetaṃ gṛhāṇa harivallabhe ॥
śrī varalakṣmī devatāyai namaḥ naivedyaṃ samarpayāmi ॥
ghanasāra sugaṃdhena miśritaṃ puṣpavāsitaṃ ।
pānīyaṃ gṛhyatāṃ devī śītalaṃ sumanoharaṃ ॥
śrī varalakṣmī devatāyai namaḥ pānīyaṃ samarpayāmi ॥
pūgīphala samāyuktaṃ nāgavallī dal̤airyutaṃ ।
karpūra cūrṇa saṃyuktaṃ tāṃbūlaṃ pratigṛhyatāṃ ॥
śrī varalakṣmī devatāyai namaḥ tāṃbūlaṃ samarpayāmi ॥',
        'Shadrasopetam, "complete in the six tastes". The verse asks for a balanced meal, not a sweet. What the household actually cooks that morning is what is meant.', 'all', true, false,
        null, 'StotraNidhi Sri Varalakshmi Vrata Kalpam (Telugu), round-trip verified by scripts/parse-varalakshmi-kalpam.mjs; the five prana mantras are the standard Smartha naivedyam frame; Sathya Vadyar, Varalakshmi Poojai 2026 step by step, chapter at 47:34')
on conflict (pooja_id, step_number) do update set
  step_title_en = excluded.step_title_en, step_title_ta = excluded.step_title_ta,
  instruction_en = excluded.instruction_en, instruction_ta = excluded.instruction_ta,
  mantra_sanskrit = excluded.mantra_sanskrit, mantra_tamil = excluded.mantra_tamil,
  mantra_translit = excluded.mantra_translit, philosophy_en = excluded.philosophy_en,
  is_dynamic_sankalpam = excluded.is_dynamic_sankalpam,
  namavali_id = excluded.namavali_id, modes = excluded.modes,
  phase = excluded.phase, source_ref = excluded.source_ref;

-- 20. Karpura Neerajanam
insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('varalakshmi_vratham', 20, 'uttara', '{main,punar,udvasana}',
        'Karpura Neerajanam', 'கர்ப்பூர நீராஜனம்',
        'Light the camphor and circle it three times clockwise, at the feet, then the middle, then the face. Ring the bell with the left hand. This is the point the rest of the house is called in.',
        'கற்பூரம் ஏற்றி மூன்று முறை வலஞ்சுழியாகச் சுற்றவும் — பாதம், பின் நடு, பின் முகம். இடது கையால் மணி அடிக்கவும். வீட்டில் உள்ளவர்களை அழைக்க வேண்டிய நேரம் இதுவே.',
        'नीराजनं समानीतं कर्पूरेण समन्वितं ।
तुभ्यं दास्याम्यहं देवि गृह्यतां विष्णुवल्लभे ॥
श्री वरलक्ष्मी देवतायै नमः नीराजनं समर्पयामि ॥',
        'நீராஜநம் ஸமாநீதம் கர்பூரேண ஸமந்விதம் ।
துப்யம் தாஸ்யாம்யஹம் தேவி க்ருஹ்யதாம் விஷ்ணுவல்லபே ॥
ஶ்ரீ வரலக்ஷ்மீ தேவதாயை நம꞉ நீராஜநம் ஸமர்பயாமி ॥',
        'nīrājanaṃ samānītaṃ karpūreṇa samanvitaṃ ।
tubhyaṃ dāsyāmyahaṃ devi gṛhyatāṃ viṣṇuvallabhe ॥
śrī varalakṣmī devatāyai namaḥ nīrājanaṃ samarpayāmi ॥',
        'Camphor leaves no residue. It is the one substance in the pooja that is entirely consumed by its own flame, which is the whole of what the deeparadhana is saying.', 'all', true, false,
        null, 'StotraNidhi Sri Varalakshmi Vrata Kalpam (Telugu), round-trip verified by scripts/parse-varalakshmi-kalpam.mjs; Sathya Vadyar, Varalakshmi Poojai 2026 step by step, chapter at 51:18')
on conflict (pooja_id, step_number) do update set
  step_title_en = excluded.step_title_en, step_title_ta = excluded.step_title_ta,
  instruction_en = excluded.instruction_en, instruction_ta = excluded.instruction_ta,
  mantra_sanskrit = excluded.mantra_sanskrit, mantra_tamil = excluded.mantra_tamil,
  mantra_translit = excluded.mantra_translit, philosophy_en = excluded.philosophy_en,
  is_dynamic_sankalpam = excluded.is_dynamic_sankalpam,
  namavali_id = excluded.namavali_id, modes = excluded.modes,
  phase = excluded.phase, source_ref = excluded.source_ref;

-- 21. Pushpanjali & Mantra Pushpam
insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('varalakshmi_vratham', 21, 'uttara', '{main,punar,udvasana}',
        'Pushpanjali & Mantra Pushpam', 'புஷ்பாஞ்ஜலி & மந்த்ர புஷ்பம்',
        'Take flowers in both cupped palms, recite, and offer them at her feet at the end of the verse.',
        'இரு கைகளையும் குவித்துப் புஷ்பங்களை எடுத்து, ஸ்லோகத்தைச் சொல்லி, முடிவில் திருவடிகளில் சமர்ப்பிக்கவும்.',
        'पद्मासने पद्मकरे सर्वलोकैकपूजिते ।
नारयणप्रिये देवी सुप्रीता भव सर्वदा ॥
श्री वरलक्ष्मी देवतायै नमः मंत्रपुष्पं समर्पयामि ॥',
        'பத்மாஸநே பத்மகரே ஸர்வலோகைகபூஜிதே ।
நாரயணப்ரியே தேவீ ஸுப்ரீதா பவ ஸர்வதா ॥
ஶ்ரீ வரலக்ஷ்மீ தேவதாயை நம꞉ மம்த்ரபுஷ்பம் ஸமர்பயாமி ॥',
        'padmāsane padmakare sarvalokaikapūjite ।
nārayaṇapriye devī suprītā bhava sarvadā ॥
śrī varalakṣmī devatāyai namaḥ maṃtrapuṣpaṃ samarpayāmi ॥',
        'The same verse as the dhyanam at the start. The pooja ends by saying what it opened with, which is how it marks that nothing in between was transactional.', 'all', true, false,
        null, 'StotraNidhi Sri Varalakshmi Vrata Kalpam (Telugu), round-trip verified by scripts/parse-varalakshmi-kalpam.mjs; Sathya Vadyar, Varalakshmi Poojai 2026 step by step, chapter at 53:31')
on conflict (pooja_id, step_number) do update set
  step_title_en = excluded.step_title_en, step_title_ta = excluded.step_title_ta,
  instruction_en = excluded.instruction_en, instruction_ta = excluded.instruction_ta,
  mantra_sanskrit = excluded.mantra_sanskrit, mantra_tamil = excluded.mantra_tamil,
  mantra_translit = excluded.mantra_translit, philosophy_en = excluded.philosophy_en,
  is_dynamic_sankalpam = excluded.is_dynamic_sankalpam,
  namavali_id = excluded.namavali_id, modes = excluded.modes,
  phase = excluded.phase, source_ref = excluded.source_ref;

-- 22. Pradakshina
insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('varalakshmi_vratham', 22, 'uttara', '{main,punar,udvasana}',
        'Pradakshina', 'ப்ரதக்ஷிணம்',
        'Go round three times, clockwise, in the space you have. If there is no room to walk, turn in place where you are sitting.',
        'இடம் இருக்கும் அளவுக்கு மூன்று முறை வலம் வரவும். நடக்க இடமில்லையென்றால், அமர்ந்த இடத்திலேயே சுற்றித் திரும்பவும்.',
        'यानिकानि च पापानि जन्मांतर कृतानि च
तानि तानि प्रणश्यंति प्रदक्षिण पदे पदे ।
पापोऽहं पापकर्माहं पापात्मा पापसंभवा
त्राहि मां कृपया देवि शरणागतवत्सले ।
अन्यथा शरणं नास्ति त्वमेव शरणं मम
तस्मात्कारुण्यभावेन रक्षरक्ष जनार्दनि ॥
श्री वरलक्ष्मी देवतायै नमः प्रदक्षिणं समर्पयामि ॥',
        'யாநிகாநி ச பாபாநி ஜந்மாம்தர க்ருதாநி ச
தாநி தாநி ப்ரணஶ்யம்தி ப்ரதக்ஷிண பதே பதே ।
பாபோऽஹம் பாபகர்மாஹம் பாபாத்மா பாபஸம்பவா
த்ராஹி மாம் க்ருபயா தேவி ஶரணாகதவத்ஸலே ।
அந்யதா ஶரணம் நாஸ்தி த்வமேவ ஶரணம் மம
தஸ்மாத்காருண்யபாவேந ரக்ஷரக்ஷ ஜநார்தநி ॥
ஶ்ரீ வரலக்ஷ்மீ தேவதாயை நம꞉ ப்ரதக்ஷிணம் ஸமர்பயாமி ॥',
        'yānikāni ca pāpāni janmāṃtara kṛtāni ca
tāni tāni praṇaśyaṃti pradakṣiṇa pade pade ।
pāpo''haṃ pāpakarmāhaṃ pāpātmā pāpasaṃbhavā
trāhi māṃ kṛpayā devi śaraṇāgatavatsale ।
anyathā śaraṇaṃ nāsti tvameva śaraṇaṃ mama
tasmātkāruṇyabhāvena rakṣarakṣa janārdani ॥
śrī varalakṣmī devatāyai namaḥ pradakṣiṇaṃ samarpayāmi ॥',
        'Papo''ham papakarmaham, "I am the wrong and the wrongdoing". The verse is unusually blunt, and it is recited while walking rather than sitting, which keeps it from becoming a performance of humility.', 'all', true, false,
        null, 'StotraNidhi Sri Varalakshmi Vrata Kalpam (Telugu), round-trip verified by scripts/parse-varalakshmi-kalpam.mjs; Sathya Vadyar, Varalakshmi Poojai 2026 step by step, chapter at 54:49')
on conflict (pooja_id, step_number) do update set
  step_title_en = excluded.step_title_en, step_title_ta = excluded.step_title_ta,
  instruction_en = excluded.instruction_en, instruction_ta = excluded.instruction_ta,
  mantra_sanskrit = excluded.mantra_sanskrit, mantra_tamil = excluded.mantra_tamil,
  mantra_translit = excluded.mantra_translit, philosophy_en = excluded.philosophy_en,
  is_dynamic_sankalpam = excluded.is_dynamic_sankalpam,
  namavali_id = excluded.namavali_id, modes = excluded.modes,
  phase = excluded.phase, source_ref = excluded.source_ref;

-- 23. Namaskaram & Varalakshmi Prarthana
insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('varalakshmi_vratham', 23, 'uttara', '{main,punar,udvasana}',
        'Namaskaram & Varalakshmi Prarthana', 'நமஸ்காரம் & வரலக்ஷ்மி ப்ரார்த்தனை',
        'Prostrate and then ask. Women prostrate with five limbs touching, not eight.',
        'நமஸ்கரித்துப் பின் வேண்டிக்கொள்ளவும். பெண்கள் அஷ்டாங்கமாக அல்ல, பஞ்சாங்கமாக நமஸ்கரிக்க வேண்டும்.',
        'नमस्ते लोकजननि नमस्ते विष्णुवल्लभे ।
पाहिमां भक्तवरदे वरलक्ष्मी नमो नमः ॥
श्री वरलक्ष्मी देवतायै नमः नमस्कारान् समर्पयामि ॥',
        'நமஸ்தே லோகஜநநி நமஸ்தே விஷ்ணுவல்லபே ।
பாஹிமாம் பக்தவரதே வரலக்ஷ்மீ நமோ நம꞉ ॥
ஶ்ரீ வரலக்ஷ்மீ தேவதாயை நம꞉ நமஸ்காராந் ஸமர்பயாமி ॥',
        'namaste lokajanani namaste viṣṇuvallabhe ।
pāhimāṃ bhaktavarade varalakṣmī namo namaḥ ॥
śrī varalakṣmī devatāyai namaḥ namaskārān samarpayāmi ॥',
        'Lokajanani, mother of the world, before Vishnuvallabha, beloved of Vishnu. The order of the two epithets is the whole argument for why this vratham is kept by women for the household rather than for themselves.', 'all', true, false,
        null, 'StotraNidhi Sri Varalakshmi Vrata Kalpam (Telugu), round-trip verified by scripts/parse-varalakshmi-kalpam.mjs; Sathya Vadyar, Varalakshmi Poojai 2026 step by step, chapter at 55:44')
on conflict (pooja_id, step_number) do update set
  step_title_en = excluded.step_title_en, step_title_ta = excluded.step_title_ta,
  instruction_en = excluded.instruction_en, instruction_ta = excluded.instruction_ta,
  mantra_sanskrit = excluded.mantra_sanskrit, mantra_tamil = excluded.mantra_tamil,
  mantra_translit = excluded.mantra_translit, philosophy_en = excluded.philosophy_en,
  is_dynamic_sankalpam = excluded.is_dynamic_sankalpam,
  namavali_id = excluded.namavali_id, modes = excluded.modes,
  phase = excluded.phase, source_ref = excluded.source_ref;

-- 24. Nonbu Sharadu Pooja
insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('varalakshmi_vratham', 24, 'uttara', '{main}',
        'Nonbu Sharadu Pooja', 'நோன்பு சரடு பூஜை',
        'Take the yellow thread of nine strands with nine knots and place it before the kalasham. Worship each knot in turn with its own name of Lakshmi, offering akshatai or a flower at each. The thread is prepared beforehand: turmeric-dyed, nine strands, nine knots.',
        'ஒன்பது இழைகளும் ஒன்பது முடிச்சுகளும் கொண்ட மஞ்சள் சரடை எடுத்து கலசத்தின் முன் வைக்கவும். ஒவ்வொரு முடிச்சையும் அதற்குரிய லக்ஷ்மி நாமத்தால் பூஜித்து, அக்ஷதையோ புஷ்பமோ சமர்ப்பிக்கவும். சரடு முன்பே தயாரிக்கப்பட வேண்டும் — மஞ்சளில் தோய்த்து, ஒன்பது இழை, ஒன்பது முடிச்சு.',
        null,
        null,
        null,
        'Nine knots, nine names, and the thread stays on the wrist for the year. It is the only part of the whole morning that leaves the pooja room, which is why this step and the tying that follows are the two the vratham is actually named for.', 'all', true, false,
        null, 'StotraNidhi Sri Varalakshmi Vrata Kalpam (Telugu), round-trip verified by scripts/parse-varalakshmi-kalpam.mjs (tora granthi puja); Sathya Vadyar, Varalakshmi Poojai 2026 step by step, chapter at 57:08')
on conflict (pooja_id, step_number) do update set
  step_title_en = excluded.step_title_en, step_title_ta = excluded.step_title_ta,
  instruction_en = excluded.instruction_en, instruction_ta = excluded.instruction_ta,
  mantra_sanskrit = excluded.mantra_sanskrit, mantra_tamil = excluded.mantra_tamil,
  mantra_translit = excluded.mantra_translit, philosophy_en = excluded.philosophy_en,
  is_dynamic_sankalpam = excluded.is_dynamic_sankalpam,
  namavali_id = excluded.namavali_id, modes = excluded.modes,
  phase = excluded.phase, source_ref = excluded.source_ref;

-- 25. Sharadu Dharanam
insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('varalakshmi_vratham', 25, 'uttara', '{main}',
        'Sharadu Dharanam', 'சரடு தாரணம்',
        'Tie the thread on the right wrist, reciting. An elder in the house ties it for the younger women; each ties her own if there is no one to. It stays on until it wears through, or until next year''s vratham.',
        'வலது மணிக்கட்டில் சரட்டைக் கட்டிக்கொள்ளவும், ஸ்லோகம் சொல்லியபடி. வீட்டில் மூத்தவர் இளையவர்களுக்குக் கட்டுவார்; கட்ட ஆள் இல்லையெனில் தானே கட்டிக்கொள்ளலாம். அறுந்து போகும் வரை, அல்லது அடுத்த வருட விரதம் வரை, அது கையிலேயே இருக்கும்.',
        'बध्नामि दक्षिणेहस्ते नवसूत्रं शुभप्रदं ।
पुत्र पौत्राभि वृद्धिं च सौभाग्यं देहि मे रमे ॥',
        'பத்நாமி தக்ஷிணேஹஸ்தே நவஸூத்ரம் ஶுபப்ரதம் ।
புத்ர பௌத்ராபி வ்ருத்திம் ச ஸௌபாக்யம் தேஹி மே ரமே ॥',
        'badhnāmi dakṣiṇehaste navasūtraṃ śubhapradaṃ ।
putra pautrābhi vṛddhiṃ ca saubhāgyaṃ dehi me rame ॥',
        'Badhnami dakshine haste, "I tie it on the right hand". The verb is first person: nobody ties it for you in the text, whatever happens in the room.', 'all', true, false,
        null, 'StotraNidhi Sri Varalakshmi Vrata Kalpam (Telugu), round-trip verified by scripts/parse-varalakshmi-kalpam.mjs (tora bandhana mantram); Sathya Vadyar, Varalakshmi Poojai 2026 step by step, chapter at 59:38')
on conflict (pooja_id, step_number) do update set
  step_title_en = excluded.step_title_en, step_title_ta = excluded.step_title_ta,
  instruction_en = excluded.instruction_en, instruction_ta = excluded.instruction_ta,
  mantra_sanskrit = excluded.mantra_sanskrit, mantra_tamil = excluded.mantra_tamil,
  mantra_translit = excluded.mantra_translit, philosophy_en = excluded.philosophy_en,
  is_dynamic_sankalpam = excluded.is_dynamic_sankalpam,
  namavali_id = excluded.namavali_id, modes = excluded.modes,
  phase = excluded.phase, source_ref = excluded.source_ref;

-- 26. Vayana Dhanam
insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('varalakshmi_vratham', 26, 'uttara', '{main}',
        'Vayana Dhanam', 'வாயன தானம்',
        'Give the vayanam: twelve of what was cooked, with betel, areca and dakshinai, to a brahmana or to another sumangali. The giver and receiver both say the verse, which names Lakshmi as both.',
        'வாயனம் கொடுக்கவும் — சமைத்ததில் பன்னிரண்டு, வெற்றிலை பாக்கு தட்சிணையுடன், ஒரு அந்தணருக்கோ அல்லது மற்றொரு சுமங்கலிக்கோ. கொடுப்பவரும் பெறுபவரும் இந்த ஸ்லோகத்தைச் சொல்வார்கள்; அதில் லக்ஷ்மியே இருவருமாகக் குறிக்கப்படுகிறாள்.',
        'एवं संपूज्य कळ्याणीं वरलक्ष्मीं स्वशक्ततः ।
दातव्यं द्वादशापूपं वायनं हि द्विजातये ॥
इंदिरा प्रतिगृह्णातु इंदिरायै ददाति च ।
इंदिरा तारकोभाभ्यां इंदिरायै नमो नमः ॥',
        'ஏவம் ஸம்பூஜ்ய கள்யாணீம் வரலக்ஷ்மீம் ஸ்வஶக்தத꞉ ।
தாதவ்யம் த்வாதஶாபூபம் வாயநம் ஹி த்விஜாதயே ॥
இம்திரா ப்ரதிக்ருஹ்ணாது இம்திராயை ததாதி ச ।
இம்திரா தாரகோபாப்யாம் இம்திராயை நமோ நம꞉ ॥',
        'evaṃ saṃpūjya kal̤yāṇīṃ varalakṣmīṃ svaśaktataḥ ।
dātavyaṃ dvādaśāpūpaṃ vāyanaṃ hi dvijātaye ॥
iṃdirā pratigṛhṇātu iṃdirāyai dadāti ca ।
iṃdirā tārakobhābhyāṃ iṃdirāyai namo namaḥ ॥',
        'Indira pratigrihnatu indirayai dadati cha, "Lakshmi receives, and it is to Lakshmi that it is given". The verse refuses to let either party be the superior one, which is the only way a gift between neighbours survives being ritualised.', 'all', true, false,
        null, 'StotraNidhi Sri Varalakshmi Vrata Kalpam (Telugu), round-trip verified by scripts/parse-varalakshmi-kalpam.mjs (vayana vidhi and vayana dana mantram); Sathya Vadyar, Varalakshmi Poojai 2026 step by step, chapter at 1:02:16')
on conflict (pooja_id, step_number) do update set
  step_title_en = excluded.step_title_en, step_title_ta = excluded.step_title_ta,
  instruction_en = excluded.instruction_en, instruction_ta = excluded.instruction_ta,
  mantra_sanskrit = excluded.mantra_sanskrit, mantra_tamil = excluded.mantra_tamil,
  mantra_translit = excluded.mantra_translit, philosophy_en = excluded.philosophy_en,
  is_dynamic_sankalpam = excluded.is_dynamic_sankalpam,
  namavali_id = excluded.namavali_id, modes = excluded.modes,
  phase = excluded.phase, source_ref = excluded.source_ref;

-- 27. Ksheera Arghyam
insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('varalakshmi_vratham', 27, 'uttara', '{main,punar,udvasana}',
        'Ksheera Arghyam', 'க்ஷீர அர்க்யம்',
        'Mix a little water into raw milk. Holding the uddharani, offer the arghyam three times. Half a glass of raw milk is kept aside for this at the start, which is why it is on the samagri list.',
        'பச்சைப் பாலில் சிறிது ஜலம் கலக்கவும். உத்தரிணியைப் பிடித்து மூன்று முறை அர்க்யம் விடவும். இதற்காகவே அரை டம்ளர் பச்சைப் பால் தொடக்கத்திலேயே தனியாக வைக்கப்படுகிறது; அதனால்தான் அது சாமக்ரி பட்டியலில் உள்ளது.',
        'शुद्धोदकं च पात्रस्थं गंध पुष्पादि मिश्रितं ।
अर्घ्यं दास्यामि ते देवी गृह्यतां हरिवल्लभे ॥
श्री वरलक्ष्मी देवतायै नमः अर्घ्यं समर्पयामि ॥',
        'ஶுத்தோதகம் ச பாத்ரஸ்தம் கம்த புஷ்பாதி மிஶ்ரிதம் ।
அர்க்யம் தாஸ்யாமி தே தேவீ க்ருஹ்யதாம் ஹரிவல்லபே ॥
ஶ்ரீ வரலக்ஷ்மீ தேவதாயை நம꞉ அர்க்யம் ஸமர்பயாமி ॥',
        'śuddhodakaṃ ca pātrasthaṃ gaṃdha puṣpādi miśritaṃ ।
arghyaṃ dāsyāmi te devī gṛhyatāṃ harivallabhe ॥
śrī varalakṣmī devatāyai namaḥ arghyaṃ samarpayāmi ॥',
        'Arghyam is given when a guest arrives and again when they leave. Giving it in milk at the close returns the courtesy the whole morning has been.', 'all', true, false,
        null, 'Arghyam verse from StotraNidhi Sri Varalakshmi Vrata Kalpam (Telugu), round-trip verified by scripts/parse-varalakshmi-kalpam.mjs; the kalpam gives it once, as an upachara, while the video gives it again in milk at the close. Sathya Vadyar, Varalakshmi Poojai 2026 step by step, chapter at 1:05:34')
on conflict (pooja_id, step_number) do update set
  step_title_en = excluded.step_title_en, step_title_ta = excluded.step_title_ta,
  instruction_en = excluded.instruction_en, instruction_ta = excluded.instruction_ta,
  mantra_sanskrit = excluded.mantra_sanskrit, mantra_tamil = excluded.mantra_tamil,
  mantra_translit = excluded.mantra_translit, philosophy_en = excluded.philosophy_en,
  is_dynamic_sankalpam = excluded.is_dynamic_sankalpam,
  namavali_id = excluded.namavali_id, modes = excluded.modes,
  phase = excluded.phase, source_ref = excluded.source_ref;

-- 28. Kshama Prarthana & Conclusion
insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('varalakshmi_vratham', 28, 'uttara', '{main,punar,udvasana}',
        'Kshama Prarthana & Conclusion', 'க்ஷமா ப்ரார்த்தனை & நிறைவு',
        'Ask forgiveness for what was short: the mantras mispronounced, the steps done wrongly, the attention that wandered. Then release akshatai and water, and the pooja is complete.',
        'குறைந்தவற்றுக்கு மன்னிப்பு வேண்டவும் — தவறாக உச்சரித்த மந்திரங்கள், பிழையாகச் செய்த படிகள், அலைந்த கவனம். பின் அக்ஷதையையும் ஜலத்தையும் விடவும்; பூஜை நிறைவுற்றது.',
        'यस्य स्मृत्या च नामोक्त्या तपः पूजाक्रियादिषु ।
न्यूनं संपूर्णतां याति सद्योवंदे तमच्युतं ॥
मंत्रहीनं क्रियाहीनं भक्तिहीनं महेश्वरि ।
यत्पूजितं मया देवी परिपूर्णं तदस्तुते ॥
अनया कल्पोक्त प्रकारेण कृतया षोडशोपचार पूजया भगवती सर्वात्मिका श्री वरलक्ष्मी देवता सुप्रीता सुप्रसन्ना वरदा भवतु ॥
मम इष्टकाम्यार्थ सिद्धिरस्तुः ॥',
        'யஸ்ய ஸ்ம்ருத்யா ச நாமோக்த்யா தப꞉ பூஜாக்ரியாதிஷு ।
ந்யூநம் ஸம்பூர்ணதாம் யாதி ஸத்யோவம்தே தமச்யுதம் ॥
மம்த்ரஹீநம் க்ரியாஹீநம் பக்திஹீநம் மஹேஶ்வரி ।
யத்பூஜிதம் மயா தேவீ பரிபூர்ணம் ததஸ்துதே ॥
அநயா கல்போக்த ப்ரகாரேண க்ருதயா ஷோடஶோபசார பூஜயா பகவதீ ஸர்வாத்மிகா ஶ்ரீ வரலக்ஷ்மீ தேவதா ஸுப்ரீதா ஸுப்ரஸந்நா வரதா பவது ॥
மம இஷ்டகாம்யார்த ஸித்திரஸ்து꞉ ॥',
        'yasya smṛtyā ca nāmoktyā tapaḥ pūjākriyādiṣu ।
nyūnaṃ saṃpūrṇatāṃ yāti sadyovaṃde tamacyutaṃ ॥
maṃtrahīnaṃ kriyāhīnaṃ bhaktihīnaṃ maheśvari ।
yatpūjitaṃ mayā devī paripūrṇaṃ tadastute ॥
anayā kalpokta prakāreṇa kṛtayā ṣoḍaśopacāra pūjayā bhagavatī sarvātmikā śrī varalakṣmī devatā suprītā suprasannā varadā bhavatu ॥
mama iṣṭakāmyārtha siddhirastuḥ ॥',
        'Mantraheenam kriyaheenam bhaktiheenam. The verse concedes all three at once, including the devotion, and asks that it be counted complete anyway. It is the reason a household pooja done imperfectly is still a pooja.', 'all', true, false,
        null, 'StotraNidhi Sri Varalakshmi Vrata Kalpam (Telugu), round-trip verified by scripts/parse-varalakshmi-kalpam.mjs; recited at the close in Sathya Vadyar, Varalakshmi Poojai 2026 step by step')
on conflict (pooja_id, step_number) do update set
  step_title_en = excluded.step_title_en, step_title_ta = excluded.step_title_ta,
  instruction_en = excluded.instruction_en, instruction_ta = excluded.instruction_ta,
  mantra_sanskrit = excluded.mantra_sanskrit, mantra_tamil = excluded.mantra_tamil,
  mantra_translit = excluded.mantra_translit, philosophy_en = excluded.philosophy_en,
  is_dynamic_sankalpam = excluded.is_dynamic_sankalpam,
  namavali_id = excluded.namavali_id, modes = excluded.modes,
  phase = excluded.phase, source_ref = excluded.source_ref;

-- 29. Udvasanam
insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('varalakshmi_vratham', 29, 'uttara', '{udvasana}',
        'Udvasanam', 'உத்வாசனம்',
        'The next day, after the Punar Pooja. Move the kalasham slightly from its seat to release what was established at Prana Pratishtha, then take leave. The water is poured at the tulasi or in the garden, the rice is cooked and eaten, and the coconut is broken. The thread stays on the wrist.',
        'மறுநாள், புனர் பூஜைக்குப் பின். ப்ராண ப்ரதிஷ்டையில் நிலைபெறச் செய்ததை விடுவிக்க, கலசத்தை அதன் இடத்திலிருந்து சிறிது நகர்த்தி விடைபெறவும். ஜலத்தைத் துளசியடியிலோ தோட்டத்திலோ ஊற்றவும், அரிசியைச் சமைத்து உண்ணவும், தேங்காயை உடைக்கவும். சரடு மட்டும் கையிலேயே இருக்கும்.',
        'यज्ञेन यज्ञमयजन्त देवाः तानि धर्माणि प्रथमान्यासन् । श्री वरलक्ष्मी देवतायै नमः यथास्थानं उद्वासयामि ॥',
        'யஜ்ஞேந யஜ்ஞமயஜந்த தேவா꞉ தாநி தர்மாணி ப்ரதமாந்யாஸந் । ஶ்ரீ வரலக்ஷ்மீ தேவதாயை நம꞉ யதாஸ்தாநம் உத்வாஸயாமி ॥',
        'yajñena yajñamayajanta devāḥ tāni dharmāṇi prathamānyāsan । śrī varalakṣmī devatāyai namaḥ yathāsthānaṃ udvāsayāmi ॥',
        'Prana Pratishtha made the kalasham a presence, so something has to end that. Without Udvasanam the vratham is not closed, and the vessels are simply put away with a guest still in them.', 'all', true, false,
        null, 'Tamil Smartha paddhati; Sathya Vadyar, Varalakshmi Poojai 2026 step by step, Next Day Punar Pooja chapter at 1:08:43')
on conflict (pooja_id, step_number) do update set
  step_title_en = excluded.step_title_en, step_title_ta = excluded.step_title_ta,
  instruction_en = excluded.instruction_en, instruction_ta = excluded.instruction_ta,
  mantra_sanskrit = excluded.mantra_sanskrit, mantra_tamil = excluded.mantra_tamil,
  mantra_translit = excluded.mantra_translit, philosophy_en = excluded.philosophy_en,
  is_dynamic_sankalpam = excluded.is_dynamic_sankalpam,
  namavali_id = excluded.namavali_id, modes = excluded.modes,
  phase = excluded.phase, source_ref = excluded.source_ref;

