values
  ('varalakshmi_vratham', 'primary', 1, 'Payasam', 'பாயசம்', 'Milk and rice or vermicelli, sweetened, the offering Lakshmi is given first.', 'பாலும் அரிசியும் அல்லது சேமியாவும், இனிப்பு சேர்த்தது; லக்ஷ்மிக்கு முதலில் படைக்கப்படுவது.'),
  ('varalakshmi_vratham', 'primary', 2, 'Kozhukattai, sweet and salt', 'கொழுக்கட்டை (இனிப்பு & உப்பு)', 'Rice flour dumplings, steamed, both kinds made on this day.', 'அரிசி மாவு கொழுக்கட்டை, ஆவியில் வேகவைத்தது; இந்நாளில் இரண்டு வகையும் செய்யப்படும்.'),
  ('varalakshmi_vratham', 'secondary', 1, 'Annam', 'அன்னம்', 'Plain cooked rice, offered with the rest of the meal.', 'வெறும் சாதம், மற்ற உணவுடன் சேர்த்துப் படைக்கப்படுகிறது.'),
  ('varalakshmi_vratham', 'secondary', 2, 'Idli', 'இட்லி', null, null),
  ('varalakshmi_vratham', 'secondary', 3, 'Vadai', 'வடை', null, null),
  ('varalakshmi_vratham', 'secondary', 4, 'Mixed fruits with banana', 'கலவை பழங்கள் & வாழைப்பழம்', 'Banana is not optional; the rest is what the season has.', 'வாழைப்பழம் கட்டாயம்; மற்றவை பருவத்தைப் பொறுத்தது.'),
  ('varalakshmi_vratham', 'secondary', 5, 'Thengai (coconut)', 'தேங்காய்', 'Optional in the vadyar''s list.', 'வாத்யாரின் பட்டியலில் விருப்பத்திற்குரியது.')
